export const learningContract = Object.freeze({
  driving_question: 'What must the facility deliver for the workload to count as successful?',
  fixed_boundary: 'Each original example declares its memory, system AC, request or job-cycle boundary. Hardware and quality stay fixed within each comparison.',
  changed_variable: 'Workspace, memory partition, time waiting, batch policy and independent job offsets are changed separately.',
  primary_payoff: 'Translate accepted work and its timing into measurable infrastructure requirements.',
  misconception: 'A rack count, high utilization or low mean power establishes useful service.',
  closing_question: 'Which memory, latency and peak-demand screens does the changed brief fail, and what must be measured next?',
});
export const initialState = { service:'training', resource:'compute', workspace:20, devices:2, partition:'balanced', observation:'A', energyCase:'B', batch:1, arrivals:6, schedule:'sync', relation:'independent', resolution:'trace', latency:30, acceptanceReveal:false, transferReveal:false };
const brief='d02-workload-brief', productive='d02-productive-utilization', phases='d02-phases-and-envelopes';
const choice=(key,label,options)=>({key,label,options});
export const scenes = [
 {id:'success-brief',label:'Define success',title:'“64 accelerators” tells us what to buy, but not what must succeed.',reference:brief,pedagogical_role:'problem',boundary:'Start with an accepted job or service. Equipment counts follow the measurements.',controls:[choice('service','Workload',[['training','Training'],['inference','Interactive inference']])],explanation:['Training needs a stated completed job or validated progress target and a deadline. Interactive inference needs accepted requests under an arrival pattern and response-time requirement. The same accelerator request can hide either problem.','An accepted result meets the agreed correctness and quality conditions. For training, processing examples does not by itself establish convergence. For inference, a fast answer of the wrong quality is not accepted work. Specify the model, implementation, numerical representation, inputs, outputs, concurrency and measurement period before estimating equipment.']},
 {id:'model-work',label:'Training / inference',title:'Training updates model state; inference uses a configured model.',reference:brief,pedagogical_role:'mechanism',boundary:'Functional information flow. The boxes are operations, not a chip layout.',controls:[choice('service','Follow',[['training','Training update'],['inference','Inference response']])],explanation:['A model contains parameters: numerical values that shape its output. Training processes examples, evaluates an objective and computes an update to those parameters. Gradients and optimizer state support that update and add memory requirements.','Inference applies the configured model to inputs. It still needs working memory and may maintain request state or cache. “Uses a configured model” does not mean a request has no changing state. Here we distinguish parameter learning from producing outputs; implementation details vary.']},
 {id:'resource-paths',label:'Locate each demand',title:'The job’s timeline connects memory, processors, networks and storage.',reference:brief,pedagogical_role:'architecture',boundary:'Generic cluster inside the D01 IT hall. Information arrows are functional transfers.',controls:[choice('resource','Inspect phase',[['input','Load inputs'],['compute','Compute'],['exchange','Exchange'],['checkpoint','Checkpoint']])],explanation:['Inputs move from storage into the compute system. Memory holds the parameters and working state that processors use. Distributed work exchanges intermediate information through the network. A checkpoint saves the required restart state to storage. The highlighted path shows which interface the selected phase depends on.','All of these devices draw electricity and reject heat; power and cooling must support the active service. Resource quantities alone do not give a completion time. Measure when the job needs each resource, what transfers can overlap and what happens when one is late. The NVIDIA architecture page supports the separate component roles; this diagram and its timing are generic.']},
 {id:'inference-memory',label:'Inference memory',title:'Parameter storage is only one part of the memory budget.',reference:brief,pedagogical_role:'balance',boundary:'Hypothetical 12B parameters · 2 bytes/parameter · decimal GB · one 80 GB device.',controls:[choice('workspace','Workspace + cache',[[20,'20 GB'],[44,'44 GB']])],explanation:['Twelve billion parameters at two bytes each occupy 24 billion bytes, or 24 decimal GB. Add the supplied workspace/cache budget and an 8 GB reservation. At 20 GB workspace the total is 52 GB, leaving 28 GB outside the declared budget.','Changing only workspace to 44 GB raises the total to 76 GB, leaving 4 GB. The device passes the arithmetic screen in both cases. The assumed workspace is not a universal multiplier; context, concurrency and implementation can change it. An allocation test and performance measurement still have to validate this brief.']},
 {id:'training-memory',label:'Training memory',title:'The same parameter count can need much more state during training.',reference:brief,pedagogical_role:'comparison',boundary:'Separate training setup · assumed 16 bytes/parameter + 64 GB activations/workspace.',controls:[choice('devices','80 GB devices',[[2,'Two'],[4,'Four']])],explanation:['The supplied training accounting includes weights, gradients, master weights and optimizer state at a combined 16 bytes per parameter. Twelve billion parameters therefore need 192 GB of state. Adding the assumed peak 64 GB activations and workspace gives 256 GB.','Two 80 GB devices total 160 GB and cannot fit the stated 256 GB even with perfect partitioning. Four total 320 GB and pass the aggregate screen, but do not yet prove the implementation fits. We have changed device count, not the model’s representation or working-memory assumption.']},
 {id:'partition-fit',label:'Four separate pools',title:'Spare memory on one device cannot rescue an overfull neighbor by itself.',reference:brief,pedagogical_role:'counterexample',boundary:'Same 256 GB total · four separate 80 GB pools · illustrative placements, not a parallelism recipe.',controls:[choice('partition','Placement',[['balanced','64 / 64 / 64 / 64 GB'],['uneven','96 / 64 / 48 / 48 GB']])],explanation:['A total of 256 GB is less than the aggregate 320 GB. Yet the uneven placement puts 96 GB on one 80 GB device. The other devices’ unused capacity does not make that allocation legal. A balanced 64 GB on each device passes this per-device memory screen.','A workable implementation also needs compatible state partitioning, buffers and communication. These bars do not establish execution correctness or scaling. Changing representation, recomputing activations or moving state can alter the budget, but each changes the problem and needs its own measured account.']},
 {id:'measured-progress',label:'From rate to job',title:'A measured rate predicts work only while its conditions continue to hold.',reference:brief,pedagogical_role:'balance',boundary:'Hypothetical benchmark input · eight devices · 400 accepted samples/s sustained for 20 h.',explanation:['The conditional calculation is 400 accepted samples per second multiplied by 20 hours and 3,600 seconds per hour: 28.8 million samples. The word sustained includes the real observation interval; if the quoted rate excludes staging, checkpoints or recovery, it cannot be applied unchanged to total job time.','More samples do not alone establish a training quality or convergence target. Nor does a measurement on eight devices establish 64-device throughput by multiplication: communication and other bottlenecks can change scaling. Measure the intended configuration and include the phases required to finish the accepted job.']},
 {id:'occupied-waiting',label:'Read aligned traces',title:'Allocated hardware can keep drawing power while useful output stops.',reference:productive,pedagogical_role:'mechanism',boundary:'Same hypothetical system AC boundary · 60 s window · compute 60 kW, wait 25 kW, idle 12 kW.',controls:[choice('observation','Observed minute',[['A','A · 45 s compute'],['B','B · 30 s compute'],['idle','No job']])],explanation:['Read all traces against the same clock. During compute, the system produces 1,000 accepted samples each second at 60 kW. During waiting, it produces no accepted samples but remains allocated and draws 25 kW. Allocation therefore remains 100% in A and B while execution time and output differ.','The no-job observation has zero allocation and output but still uses 12 kW. Allocation is reserved device-time divided by available device-time; it is not a GPU hardware occupancy counter. Communication can be useful even without arithmetic, so a phase labeled wait does not identify the cause. Synchronized storage and network traces would guide the next controlled experiment.']},
 {id:'energy-per-result',label:'Energy per result',title:'Lower average power can mean more energy for each accepted result.',reference:productive,pedagogical_role:'comparison',boundary:'Include compute and waiting energy over the same complete 60 s interval.',controls:[choice('energyCase','Compare with A',[['B','B · longer wait'],['C','C · shorter wait'],['idle','Idle · no output']])],explanation:['Case A uses 60 kW × 45 s + 25 kW × 15 s = 3,075 kJ and produces 45,000 samples: 68.3 J per accepted sample. Case B uses less energy, 2,550 kJ, but produces only 30,000 samples: 85 J per accepted sample. Waiting energy is spread across fewer accepted results.','Case C computes for 50 seconds and waits for 10: 3,250 kJ / 50,000 samples = 65 J per sample. This is an explicit changed case, not a claim that maximum power is always best. With no output, energy per sample is undefined; report the idle energy directly instead of dividing by zero. Facility overhead and changes in quality are outside this model.']},
 {id:'batching-throughput',label:'Batch execution',title:'A batch can finish more requests per second while each execution lasts longer.',reference:phases,pedagogical_role:'comparison',boundary:'Toy timings · permanently full queue · one execution instance · no queue-gathering time here.',controls:[choice('batch','Execution policy',[[1,'One request · 8 ms'],[4,'Four requests · 20 ms']])],explanation:['A batch is a group of inputs executed together. Under the supplied timings, one request takes 8 ms, yielding a full-queue capacity of 125 requests/s. Four together take 20 ms, yielding 200 requests/s. The batch completes more requests per second, even though one execution takes longer.','These timings are hypothetical measurements, not NVIDIA or MLPerf results. The actual benefit depends on the implementation and workload. Triton’s dynamic-batching documentation describes combining requests and optionally waiting for more to arrive; the next scene adds that gathering time explicitly.']},
 {id:'gathering-latency',label:'The first request waits',title:'The first request waits for the others before the batch can start.',reference:phases,pedagogical_role:'mechanism',boundary:'Four-request batch · 20 ms execution · empty queue · no network or other service delay.',controls:[choice('arrivals','Time between arrivals',[[6,'6 ms'],[12,'12 ms']])],explanation:['At six-millisecond intervals, the four requests arrive at 0, 6, 12 and 18 ms. The batch starts at 18 ms and finishes at 38 ms. Subtract each arrival from completion: response times are 38, 32, 26 and 20 ms. Waiting is longest for the first request.','Changing only the arrival interval to 12 ms delays gathering: completion moves to 56 ms and response times become 56, 44, 32 and 20 ms. A larger full-queue capacity does not promise low latency at sparse arrivals. This fixed full-group policy has no timeout; real timeout or partial-batch behavior requires new timing measurements.']},
 {id:'arrival-capacity',label:'Can the queue keep up?',title:'Removing batch-gathering time can still leave a growing queue.',reference:phases,pedagogical_role:'counterexample',boundary:'Same one-instance timings · requests every 6 ms · start with an empty queue.',controls:[choice('batch','Execution policy',[[1,'One at a time'],[4,'Groups of four']])],explanation:['One request every 6 ms is about 166.7 requests/s. Single-request execution can serve only 125 requests/s. Each subsequent arrival reaches a busier queue: the first eight response times are 8, 10, 12, 14, 16, 18, 20 and 22 ms. A short demonstration can look fast while the sustained queue grows.','Batches of four have 200 requests/s full-queue capacity, above this offered load. Under the fixed periodic arrival pattern, each group gathers for 18 ms then executes for 20 ms, with its first request seeing 38 ms. Capacity sufficiency and latency are separate tests. Add instances, alter policy or change the requirement only as explicit new cases.']},
 {id:'job-phases',label:'One job’s rhythm',title:'Compute, communication and checkpointing create different demand phases.',reference:phases,pedagogical_role:'mechanism',boundary:'One hypothetical repeating job · 30 s compute at 120 kW · 15 s exchange at 40 kW · 15 s save at 60 kW.',explanation:['Compute performs the main arithmetic; communication exchanges information needed by participants; checkpointing writes restart state to storage. Their assumed powers differ. This is one original example, not a universal training waveform.','Over 60 seconds, the job uses 120 × 30 + 40 × 15 + 60 × 15 = 5,100 kW-seconds. Dividing by 60 gives an 85 kW mean. The mean accounts for total energy, while the phase trace tells us when each resource and power level is needed.']},
 {id:'synchronized-jobs',label:'Jobs align',title:'Four jobs entering compute together produce a 480 kW peak.',reference:phases,pedagogical_role:'mechanism',boundary:'Four identical jobs · synchronized 60 s cycles · sum of the four job power boundaries.',explanation:['Read the four phase rows vertically: all four compute at once, then all communicate, then all checkpoint. Adding their powers gives 480, 160 and 240 kW. Their mean is 340 kW, but none of those phase plateaus is 340 kW.','The aggregate uses 5.667 kWh per cycle. A supply brief containing only the mean misses the 480 kW demand. The source of the synchronized timing must be understood before assuming scheduling can remove it.']},
 {id:'staggering-jobs',label:'Change only timing',title:'Offsetting independent jobs can lower the peak without changing cycle energy.',reference:phases,pedagogical_role:'comparison',boundary:'Four independent jobs · no contention or extra waiting · periodic steady state, not startup.',controls:[choice('schedule','Phase offsets',[['sync','All start together'],['staggered','Offset by 15 s']])],explanation:['Keep each job’s durations and powers fixed, but offset independent jobs by 0, 15, 30 and 45 seconds. At every instant two jobs compute, one communicates and one checkpoints: 2 × 120 + 40 + 60 = 340 kW. The same individual phase-time accounts preserve 5.667 kWh per cycle.','This ideal periodic trace excludes startup, completion, interference and recovery. Staggering is useful only if the jobs can be delayed independently without losing accepted service. It does not turn 340 kW into a universal infrastructure rating. Test how the intended schedule behaves when conditions change.']},
 {id:'independence',label:'Check the dependency',title:'Workers that must exchange results cannot be delayed as if they were separate jobs.',reference:phases,pedagogical_role:'counterexample',boundary:'Dependency illustration · no timing or power saving is predicted for the coupled job.',controls:[choice('relation','Relationship',[['independent','Four separate jobs'],['coupled','Workers in one job']])],explanation:['Four independent jobs can enter their own communication phases at different times if their deadlines and shared resources permit. Four participants in a single distributed job may instead need to reach an exchange point together before the next computation can proceed.','In the coupled view, delaying one participant means the others wait at the exchange. Their schedules and completion times change, invalidating the unchanged-phase assumption behind the flat 340 kW trace. Parallelism distributes work and state but adds coordination; it does not justify perfect scaling or arbitrary staggering.']},
 {id:'demand-transition',label:'Keep the timescale',title:'A 340 kW average hides a 320 kW change between phases.',reference:phases,pedagogical_role:'counterexample',boundary:'Four-job example · separate assumed 2 s transition · mean taken from the ideal phase-cycle case.',controls:[choice('resolution','View',[['trace','Transition detail'],['mean','Cycle mean only']])],explanation:['The synchronized compute and communication plateaus differ by 480 − 160 = 320 kW. If a supplied transition trace spans two seconds, its average rate of change is −160 kW/s over those two seconds. The visible ramp is an assumed transition detail, not a measured device response.','The 340 kW figure is the energy-equivalent mean of the idealized complete phase cycle; it cannot tell us the step duration. Adding a finite ramp to a full-cycle model would require updating that cycle’s energy account. Specify the measurement resolution needed for the equipment or control question; an average cannot validate fast behavior.']},
 {id:'acceptance-envelope',label:'Test both requirements',title:'A 200 requests/s execution capacity does not override a latency requirement.',reference:phases,pedagogical_role:'transfer',boundary:'Fixed batch-four toy service · 6 ms arrivals · required ≥120 requests/s · every request within the chosen limit.',controls:[choice('latency','Latency limit',[[30,'30 ms'],[40,'40 ms']])],reveal:'acceptanceReveal',explanation:['Predict before revealing. The full-queue capacity is 200 requests/s and the supplied arrival pattern offers 166.7 requests/s, so this toy service can keep up. Its response times are 38, 32, 26 and 20 ms. The mean is 29 ms, but the first two requests fail the “every request within 30 ms” condition.','At a 40 ms limit these numerical timing checks pass. This is not a full acceptance result: quality, actual input/output distributions, system power, availability and degraded operation remain unverified. Production services often specify a percentile rather than every request; name that percentile and the observation period explicitly rather than substituting an average.']},
 {id:'next-brief',label:'Carry the brief forward',title:'Carry the supported workload envelope into the power-supply question.',reference:brief,pedagogical_role:'transfer',boundary:'Three separate hypothetical screens · preserve each boundary · proposed conditions are visible beside each result.',reveal:'transferReveal',explanation:['The changed inference memory case totals 24 + 44 + 8 = 76 GB, so an 80 GB device passes the declared capacity screen. The batch-four request case misses a 30 ms every-request requirement because its first two latencies are 38 and 32 ms. The synchronized four-job trace reaches 480 kW and exceeds a proposed 400 kW job-power limit despite a 340 kW mean.','Revise only the failing mechanism, then measure again. A shorter gathering policy needs new timing measurements; independent staggering needs its independence and service assumptions tested. Memory fit is not a speed guarantee. Before D03 supply and siting, carry the requested accepted work, traffic/deadline, peak and time resolution, system boundary, and supported failure/maintenance conditions. If the brief lacks quality, software or recovery criteria, it is still incomplete.']},
];
